import sys
from collections import deque

def main():
    input = sys.stdin.read().split()
    ptr = 0
    n, m, s = map(int, input[ptr:ptr+3])
    ptr += 3
    adj = [[] for _ in range(n+1)]
    for _ in range(m):
        v, u, w = map(int, input[ptr:ptr+3])
        ptr += 3
        adj[v].append((u, w))
        adj[u].append((v, w))
    l = int(input[ptr])

    # Dijkstra to find shortest distances from s
    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[s] = 0
    heap = []
    import heapq
    heapq.heappush(heap, (0, s))
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for (v, w) in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))

    # BFS to find all nodes with dist[u] == l
    count = 0
    q = deque()
    for u in range(1, n+1):
        if dist[u] == l:
            count += 1
            q.append(u)

    # For edges, we need to check if l is between dist[u] and dist[v]
    # We'll process edges in a way that avoids double counting
    visited_edges = set()
    for u in range(1, n+1):
        for (v, w) in adj[u]:
            if u > v:
                continue
            if (u, v) in visited_edges:
                continue
            visited_edges.add((u, v))
            if dist[u] == l or dist[v] == l:
                continue
            if dist[u] < dist[v]:
                if dist[u] + w > l and dist[v] > l:
                    count += 1
            else:
                if dist[v] + w > l and dist[u] > l:
                    count += 1

    print(count)

main()
